	RevokeAuth(context.Context, *workbench.RevokeAuthReq) (*workbench.RevokeAuthResp, error)
	GetAuthDetail(context.Context, *workbench.GetAuthDetailReq) (*workbench.GetAuthDetailResp, error)
	// ---- SSO ----
	CreateTicket(context.Context, *workbench.CreateTicketReq) (*workbench.CreateTicketResp, error)
	GetUserByTicket(context.Context, *workbench.GetUserByTicketReq) (*workbench.GetUserByTicketResp, error)
	// ---- Notification ----
	CreateMsgTemplate(context.Context, *workbench.CreateMsgTemplateReq) (*workbench.CreateMsgTemplateResp, error)
	UpdateMsgTemplate(context.Context, *workbench.UpdateMsgTemplateReq) (*workbench.UpdateMsgTemplateResp, error)
	DeleteMsgTemplate(context.Context, *workbench.DeleteMsgTemplateReq) (*workbench.DeleteMsgTemplateResp, error)
	GetMsgTemplateList(context.Context, *workbench.GetMsgTemplateListReq) (*workbench.GetMsgTemplateListResp, error)
	PreviewMsgTemplate(context.Context, *workbench.PreviewMsgTemplateReq) (*workbench.PreviewMsgTemplateResp, error)
	SendNotify(context.Context, *workbench.SendNotifyReq) (*workbench.SendNotifyResp, error)
	BatchSendNotify(context.Context, *workbench.BatchSendNotifyReq) (*workbench.BatchSendNotifyResp, error)
	UpdateNotify(context.Context, *workbench.UpdateNotifyReq) (*workbench.UpdateNotifyResp, error)
	RevokeNotify(context.Context, *workbench.RevokeNotifyReq) (*workbench.RevokeNotifyResp, error)
	QueryNotify(context.Context, *workbench.QueryNotifyReq) (*workbench.QueryNotifyResp, error)
	GetNotifyList(context.Context, *workbench.GetNotifyListReq) (*workbench.GetNotifyListResp, error)
	GetNotifyStats(context.Context, *workbench.GetNotifyStatsReq) (*workbench.GetNotifyStatsResp, error)
	// ---- Developer ----
	RegisterDeveloper(context.Context, *workbench.RegisterDeveloperReq) (*workbench.RegisterDeveloperResp, error)
	LoginDeveloper(context.Context, *workbench.LoginDeveloperReq) (*workbench.LoginDeveloperResp, error)
	UpdateDeveloper(context.Context, *workbench.UpdateDeveloperReq) (*workbench.UpdateDeveloperResp, error)
	GetDeveloperList(context.Context, *workbench.GetDeveloperListReq) (*workbench.GetDeveloperListResp, error)
	ReviewDeveloper(context.Context, *workbench.ReviewDeveloperReq) (*workbench.ReviewDeveloperResp, error)
	DisableDeveloper(context.Context, *workbench.DisableDeveloperReq) (*workbench.DisableDeveloperResp, error)
	CreateDeveloperApp(context.Context, *workbench.CreateDeveloperAppReq) (*workbench.CreateDeveloperAppResp, error)
	SubmitApp(context.Context, *workbench.SubmitAppReq) (*workbench.SubmitAppResp, error)
	WithdrawSubmit(context.Context, *workbench.WithdrawSubmitReq) (*workbench.WithdrawSubmitResp, error)
	GetDeveloperApps(context.Context, *workbench.GetDeveloperAppsReq) (*workbench.GetDeveloperAppsResp, error)
	// ---- App Review (platform) ----
	GetPendingReviews(context.Context, *workbench.GetPendingReviewsReq) (*workbench.GetPendingReviewsResp, error)
	GetReviewDetail(context.Context, *workbench.GetReviewDetailReq) (*workbench.GetReviewDetailResp, error)
	ReviewAction(context.Context, *workbench.ReviewActionReq) (*workbench.ReviewActionResp, error)
	ForceOffline(context.Context, *workbench.ForceOfflineReq) (*workbench.ForceOfflineResp, error)
	// ---- Notification (additional) ----
	GetNotifyDetail(context.Context, *workbench.GetNotifyDetailReq) (*workbench.GetNotifyDetailResp, error)
